          setText(els.log, target === "1" ? "As WL rises, charge enters the capacitor and the cell charges toward a 1 state." : "As WL rises, charge leaves the capacitor and the cell discharges toward a 0 state.");
          setText(els.lineState, target === "1" ? "Charge entering cell" : "Charge leaving cell");
