        setText(els.helper, operationKey === "refresh" ? "Step 2: sense the remaining cell charge and check whether a 1 can still be restored." : "Step 2: when WL rises, the capacitor shares charge with the bitline and creates a tiny voltage delta.");
        setText(els.log, operationKey === "refresh" ? previewBit === "1" ? "Enough charge remains to still detect a 1, so the next restore phase can recover it." : "The remaining charge is too weak, or already gone, so the cell has tilted toward 0." : previewBit === "1" ? "The remaining charge pulls the bitline slightly above 0.5V." : "Too little charge remains, so the bitline tilts slightly below 0.5V.");
        setText(els.lineState, previewBit === "1" ? "BL = 0.5 + dV" : "BL = 0.5 - dV");
        setText(els.detailState, operationKey === "refresh" ? "Weak charge detect" : "Charge sharing");
        setText(els.blValue, previewBit === "1" ? "0.5+dV" : "0.5-dV");
        setChargeVisual(sharedCharge);
        paintLine(els.blLine, "#a78bfa", 3.4);
        paintLine(els.wlLine, "#8b5cf6", 4.2);
        paintGateLines("#8b5cf6", 1, true);
        paintRect(els.accessLeft, "#fbcfe8", "#f43f5e");
        toggleClass(els.blLine, "memory-flow-live", true);
        toggleClass(els.wlLine, "memory-flow-live", true);
        toggleClass(els.chargeFill, "memory-pulse-live", true);
        toggleClass(els.chargeValue, "memory-pulse-live", true);
