      setText(els.helper, operationKey === "refresh" ? "Refresh done: check the charge state after restore has completed." : "Read done: check the cell state after the destructive read has been restored.");
      setText(els.log, finalCharge > 0 ? `${operationKey === "refresh" ? "After refresh" : "After read and restore"}, the capacitor is fully charged again and holds a 1 state.` : `${operationKey === "refresh" ? "The refresh result" : "The read result"} leaves the cell in the 0 state.`);
      setText(els.lineState, "Charge held");
      setText(els.detailState, finalCharge > 0 ? "100% charge held" : "0 state held");
      setText(els.blValue, "Z");
      setChargeVisual(finalCharge);
      toggleClass(els.chargeFill, "memory-pulse-live", true);
      toggleClass(els.chargeValue, "memory-pulse-live", true);
      toggleClass(els.cellValue, "memory-pulse-live", true);
